exact_public_native_receipt.rules:
# SPDX-License-Identifier: MIT
# Disposable IPv4 lab only: queues 101 and 102 must be alive; nf_conntrack_acct=1 required.
# Split 6000/s + 2048 burst across bulk (4976/1024), discovery (960/960), probes (64/64).
table ip awg_kernel_guard_lab {
    set unknown_sources {
        type ipv4_addr
        flags dynamic,timeout
        timeout 5s
        gc-interval 1s
        size 4096
    }
    set discovery_sources {
        type ipv4_addr
        flags dynamic,timeout
        timeout 5s
        gc-interval 1s
        size 4096
    }
    set trusted {
        typeof ip saddr . udp sport . ct id
        flags timeout
        timeout 10s
        gc-interval 1s
        size 4096
    }
    set handshake_sources {
        type ipv4_addr
        flags dynamic,timeout
        timeout 5s
        gc-interval 1s
        size 4096
    }
    chain handshake_aggregate {
        limit rate over 100/second burst 16 packets counter drop
        counter return
    }
    chain handshake_guard {
        update @handshake_sources { ip saddr limit rate 20/second burst 8 packets } counter goto handshake_aggregate
        counter drop
    }
    chain aggregate {
        limit rate over 4976/second burst 1024 packets counter goto hold
        counter return
    }
    chain unconfirmed {
        # The optional bridge supplement replaces this chain atomically.
        counter queue to numgen inc mod 2 offset 101
    }
    chain hold {
        ct status confirmed counter queue to numgen inc mod 2 offset 101
        goto unconfirmed
    }
    chain guard {
        update @unknown_sources { ip saddr limit rate 1500/second burst 4096 packets } counter goto aggregate
        # Excess remains untrusted while held; no listener means drop.
        counter goto hold
    }
    chain trusted_flow {
        ip saddr 192.168.76.40-192.168.76.55 counter comment "trusted_noise"
        counter return comment "trusted_total"
    }
    chain early {
        type filter hook prerouting priority -150; policy accept;
        iifname "cw34br" ip daddr 192.168.76.10 ip saddr 192.168.76.20 udp sport 32497 ct direction reply return
        iifname "cw34br" ip daddr 192.168.76.10 udp dport 32497 meta mark set meta mark & 0x81ffffff
        iifname "cw34br" ip daddr 192.168.76.10 udp dport 32497 ip saddr . udp sport . ct id @trusted meta mark set meta mark | 0x10000000 goto trusted_flow
        # Reused NAT tuples can retain conntrack; discovery must not require its first packet.
        iifname "cw34br" ip daddr 192.168.76.10 udp dport 32497 update @discovery_sources { ip saddr limit rate 32/second burst 256 packets } limit rate 960/second burst 960 packets counter return comment "discovery_sample"
        iifname "cw34br" ip daddr 192.168.76.10 udp dport 32497 jump guard
    }
    chain escrow_recheck {
        meta mark set meta mark & 0xf7ffffff
        ip saddr . udp sport . ct id @trusted meta mark set meta mark | 0x10000000 counter return comment "escrow_current"
        counter drop comment "escrow_stale"
    }
    chain escrow_validate {
        type filter hook prerouting priority -146; policy accept;
        meta mark & 0x08000000 != 0 jump escrow_recheck
        meta mark & 0x04000000 != 0 jump probe_recheck
    }
    chain probe_recheck {
        meta mark set meta mark & 0xfbffffff
        limit rate over 64/second burst 64 packets counter drop
        counter return comment "escrow_probe"
    }
    chain queued {
        type filter hook prerouting priority -140; policy accept;
        iifname "cw34br" ip daddr 192.168.76.10 ip saddr 192.168.76.20 udp sport 32497 ct direction reply return
        iifname "cw34br" ip daddr 192.168.76.10 udp dport 32497 meta mark & 0x02000000 != 0 counter return comment "late_deferred"
        iifname "cw34br" ip daddr 192.168.76.10 udp dport 32497 meta mark & 0x10000000 != 0 return
        iifname "cw34br" ip daddr 192.168.76.10 udp dport 32497 queue num 100
    }
    chain classified_handshakes {
        type filter hook prerouting priority -138; policy accept;
        iifname "cw34br" ip daddr 192.168.76.10 ip saddr 192.168.76.20 udp sport 32497 ct direction reply return
        iifname "cw34br" ip daddr 192.168.76.10 udp dport 32497 meta mark & 0x02000000 != 0 return
        iifname "cw34br" ip daddr 192.168.76.10 udp dport 32497 meta mark & 0x10000000 != 0 return
        # An older filter without classification must fail closed.
        iifname "cw34br" ip daddr 192.168.76.10 udp dport 32497 meta mark & 0x40000000 == 0 counter drop
        iifname "cw34br" ip daddr 192.168.76.10 udp dport 32497 meta mark & 0x20000000 != 0 jump handshake_guard
    }
}

# SPDX-License-Identifier: MIT
# Optional routed-bridge lab path. Physical enp0s3 must be a port of cw34br;
# the entry's lab IPv4 address belongs to cw34br. No production installer.
# Load with the late-hold rule changes, before enabling late_escrow in A.
table bridge awg_escrow_bridge_lab {
    set trusted {
        typeof ct original ip saddr . ct original proto-src . ct id
        flags timeout
        timeout 10s
        gc-interval 1s
        size 4096
    }
    chain held {
        type filter hook postrouting priority 300; policy accept;
        meta mark & 0x02000000 == 0 return
        oifname "enp0s3" ether type ip ip saddr 192.168.76.10 ip daddr 192.168.76.20 udp dport 32497 ct status confirmed counter queue to numgen inc mod 2 offset 101
        counter drop comment "late_unconfirmed"
    }
    chain validate {
        type filter hook postrouting priority 301; policy accept;
        meta mark & 0x02000000 == 0 return
        ct status & 0x200 != 0 counter drop comment "late_dying"
        meta mark & 0x04000000 != 0 goto probe
        meta mark & 0x08000000 != 0 ct status confirmed ct original ip saddr . ct original proto-src . ct id @trusted meta mark set meta mark & 0xe1ffffff counter return comment "late_current"
        counter drop comment "late_stale"
    }
    chain probe {
        # C also shares one 64/s bucket across prerouting and bridge probes.
        limit rate over 64/second burst 64 packets counter drop
        meta mark set meta mark & 0x85ffffff counter return comment "late_probe"
    }
    chain probe_classify {
        type filter hook postrouting priority 302; policy accept;
        meta mark & 0x04000000 != 0 counter queue num 100 comment "late_probe_classify"
    }
    chain probe_validate {
        type filter hook postrouting priority 303; policy accept;
        meta mark & 0x04000000 == 0 return
        meta mark & 0x40000000 == 0 counter drop
        # Only transport can produce the fresh proof; do not add handshake budget.
        meta mark & 0x20000000 != 0 counter drop comment "late_control_probe_drop"
        meta mark set meta mark & 0x81ffffff counter return comment "late_probe_pass"
    }
}

# Keep this switch and bridge-table creation in one nft transaction.
flush chain ip awg_kernel_guard_lab unconfirmed
add rule ip awg_kernel_guard_lab unconfirmed meta mark set meta mark | 0x02000000 counter return
